import React, { useState } from "react";
import axios from "../utils/axios";

const EMOJIS = ["🍔","🚗","🏠","✈️","💊","🎮","📚","👗","☕","🏋️","🐶","🎵","💄","🛒","💡","📱"];

const CreateBudgetForm = ({ onSuccess }) => {
  const [name, setName] = useState("");
  const [amount, setAmount] = useState("");
  const [icon, setIcon] = useState("💰");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    const userId = localStorage.getItem("userId");
    if (!userId) { setError("Not logged in"); return; }
    setLoading(true);
    try {
      const now = new Date();
      await axios.post("/api/budgets", {
        icon, name,
        amount: parseFloat(amount),
        month: now.getMonth() + 1,
        year: now.getFullYear(),
        userId: parseInt(userId, 10),
      });
      onSuccess();
    } catch (err) {
      setError(err?.response?.data?.message || "Failed to create budget");
    } finally {
      setLoading(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} style={{ fontFamily: "'Inter', sans-serif" }}>
      {error && <div style={{ background: "#fff0f0", border: "1px solid #fecaca", color: "#dc2626", borderRadius: 8, padding: "10px 14px", fontSize: 13, marginBottom: 16 }}>{error}</div>}

      <div style={{ marginBottom: 16 }}>
        <label style={ls.label}>Icon</label>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginTop: 6 }}>
          {EMOJIS.map(e => (
            <button key={e} type="button" onClick={() => setIcon(e)}
              style={{ width: 36, height: 36, borderRadius: 8, border: `2px solid ${icon === e ? "#2563eb" : "#e8e8e6"}`, background: icon === e ? "#eff6ff" : "#fff", fontSize: 18, cursor: "pointer", transition: "all 0.1s" }}>
              {e}
            </button>
          ))}
        </div>
        <div style={{ marginTop: 8, fontSize: 12, color: "#9b9b9b" }}>Selected: <span style={{ fontSize: 20 }}>{icon}</span></div>
      </div>

      <div style={{ marginBottom: 16 }}>
        <label style={ls.label}>Budget Name</label>
        <input type="text" value={name} required placeholder="e.g. Food, Rent, Transport"
          onChange={e => setName(e.target.value)} style={ls.input}
          onFocus={e => e.target.style.borderColor = "#2563eb"}
          onBlur={e => e.target.style.borderColor = "#e8e8e6"} />
      </div>

      <div style={{ marginBottom: 24 }}>
        <label style={ls.label}>Amount (RM)</label>
        <input type="number" value={amount} required min="1" step="0.01" placeholder="500"
          onChange={e => setAmount(e.target.value)} style={ls.input}
          onFocus={e => e.target.style.borderColor = "#2563eb"}
          onBlur={e => e.target.style.borderColor = "#e8e8e6"} />
      </div>

      <button type="submit" disabled={loading} style={{ width: "100%", padding: "10px", background: "#2563eb", color: "#fff", border: "none", borderRadius: 8, fontSize: 14, fontWeight: 500, cursor: "pointer", fontFamily: "'Inter', sans-serif", opacity: loading ? 0.7 : 1 }}>
        {loading ? "Creating…" : "Create Budget"}
      </button>
    </form>
  );
};

const ls = {
  label: { display: "block", fontSize: 13, fontWeight: 500, color: "#374151", marginBottom: 6 },
  input: { width: "100%", padding: "9px 12px", border: "1px solid #e8e8e6", borderRadius: 8, fontSize: 14, color: "#191919", outline: "none", fontFamily: "'Inter', sans-serif", boxSizing: "border-box", transition: "border-color 0.15s" },
};

export default CreateBudgetForm;
